# -*- coding: utf-8 -*-
import sys, json, base64, hashlib, hmac

try:
    from Crypto.Cipher import AES as _CAES
except Exception:
    _CAES = None


_RCON = [0x01,0x02,0x04,0x08,0x10,0x20,0x40,0x80,0x1B,0x36,0x6C,0xD8,0xAB,0x4D]

def _gen_sbox():
    sbox = [0]*256
    p = q = 1
    while True:
        p = (p ^ ((p << 1) & 0xFF) ^ (0x1B if (p & 0x80) else 0)) & 0xFF
        q ^= (q << 1) & 0xFF
        q ^= (q << 2) & 0xFF
        q ^= (q << 4) & 0xFF
        if q & 0x80:
            q ^= 0x09
        x = (q ^ ((q << 1)|(q >> 7)) ^ ((q << 2)|(q >> 6)) ^
             ((q << 3)|(q >> 5)) ^ ((q << 4)|(q >> 4)))
        sbox[p] = (x ^ 0x63) & 0xFF
        if p == 1:
            break
    sbox[0] = 0x63
    return sbox

_SBOX = _gen_sbox()
_INV_SBOX = [0]*256
for _i, _v in enumerate(_SBOX):
    _INV_SBOX[_v] = _i

def _gf_mul(a, b):
    r = 0
    while b:
        if b & 1:
            r ^= a
        a <<= 1
        if a & 0x100:
            a ^= 0x11B
        b >>= 1
    return r & 0xFF

def _key_expansion(key):
    w = [list(key[i*4:i*4+4]) for i in range(8)]
    for i in range(8, 60):
        t = list(w[i-1])
        if i % 8 == 0:
            t = t[1:] + t[:1]
            t = [_SBOX[b] for b in t]
            t[0] ^= _RCON[i//8 - 1]
        elif i % 8 == 4:
            t = [_SBOX[b] for b in t]
        w.append([w[i-8][j] ^ t[j] for j in range(4)])
    return w

def _dec_block(block, w):
    s = [[block[r + 4*c] for c in range(4)] for r in range(4)]
    for c in range(4):
        for r in range(4):
            s[r][c] ^= w[56 + c][r]
    for rnd in range(13, 0, -1):
        s[1] = s[1][-1:] + s[1][:-1]
        s[2] = s[2][-2:] + s[2][:-2]
        s[3] = s[3][-3:] + s[3][:-3]
        for c in range(4):
            for r in range(4):
                s[r][c] = _INV_SBOX[s[r][c]]
        for c in range(4):
            for r in range(4):
                s[r][c] ^= w[rnd*4 + c][r]
        for c in range(4):
            a0,a1,a2,a3 = s[0][c],s[1][c],s[2][c],s[3][c]
            s[0][c] = _gf_mul(a0,14)^_gf_mul(a1,11)^_gf_mul(a2,13)^_gf_mul(a3,9)
            s[1][c] = _gf_mul(a0,9)^_gf_mul(a1,14)^_gf_mul(a2,11)^_gf_mul(a3,13)
            s[2][c] = _gf_mul(a0,13)^_gf_mul(a1,9)^_gf_mul(a2,14)^_gf_mul(a3,11)
            s[3][c] = _gf_mul(a0,11)^_gf_mul(a1,13)^_gf_mul(a2,9)^_gf_mul(a3,14)
    s[1] = s[1][-1:] + s[1][:-1]
    s[2] = s[2][-2:] + s[2][:-2]
    s[3] = s[3][-3:] + s[3][:-3]
    for c in range(4):
        for r in range(4):
            s[r][c] = _INV_SBOX[s[r][c]]
    for c in range(4):
        for r in range(4):
            s[r][c] ^= w[c][r]
    return bytes(s[r][c] for c in range(4) for r in range(4))

def aes256_cbc_decrypt(data, key, iv):
    w = _key_expansion(key)
    out = bytearray()
    prev = iv
    for i in range(0, len(data), 16):
        blk = data[i:i+16]
        out += bytes(a ^ b for a, b in zip(_dec_block(blk, w), prev))
        prev = blk
    return bytes(out)


_BLOB = ''
_RUNTIME = {'timeout': 20, 'retry': 2, 'ua': 'Mobile Safari', 'seq': [3, 0, 2, 1], 'v1': 'UNkAhY99RUguo', 'v2': 'BMQR1MtK0Jnb0', 'v3': 'HSUyfC8xlLcmL', 'v4': 'MTl3bbL6V3lY9'}
_REQUIRE_EXTERNAL = False
_key = None
_real = None

def _dec(ct, key, iv):
    if _CAES is not None:
        return _CAES.new(key, _CAES.MODE_CBC, iv).decrypt(ct)
    return aes256_cbc_decrypt(ct, key, iv)

def _derive_key(p, salt):
    return hashlib.pbkdf2_hmac("sha256", p.encode("utf-8"), salt, 200000, dklen=32)

def _embedded_key():
    d = _RUNTIME
    slots = [d['v1'], d['v2'], d['v3'], d['v4']]
    parts = [None] * 4
    for i in range(4):
        parts[d['seq'][i]] = slots[i]
    raw = base64.b64decode(''.join(parts))
    seed, masked = raw[:16], raw[16:]
    ks = b''
    n = 0
    while len(ks) < len(masked):
        ks += hashlib.sha256(seed + bytes([n])).digest()
        n += 1
    return bytes(x ^ y for x, y in zip(masked, ks)).decode('utf-8')

def _open(k):
    raw = base64.b64decode(_BLOB)
    salt, iv = raw[:16], raw[16:32]
    ct, mac = raw[32:-32], raw[-32:]
    key = _derive_key(k, salt)
    if not hmac.compare_digest(hmac.new(key, salt + iv + ct, hashlib.sha256).digest(), mac):
        raise ValueError("blob 认证失败（口令错误或已被替换）")
    pt = _dec(ct, key, iv)
    pad = pt[-1]
    if not (1 <= pad <= 16):
        raise ValueError("填充校验失败")
    return pt[:len(pt) - pad].decode('utf-8')

def _build():
    global _real
    if _real is not None:
        return
    candidates = []
    if _key:
        candidates.append(_key)                 # 可选的外部覆盖（传错会自动回退）
    if _REQUIRE_EXTERNAL:
        if not candidates:
            raise ValueError("init(ext) 未提供 key，拒绝解密")
    elif _RUNTIME:
        candidates.append(_embedded_key())      # 零配置：用内嵌口令
    last, src = None, None
    for k in candidates:
        try:
            src = _open(k)
            break
        except Exception as e:
            last = e
    if src is None:
        raise ValueError("解密失败：%s" % last)
    ns = {"__name__": "_spider_cipher_", "__file__": __file__}
    exec(src, ns)
    _real = ns["Spider"]()

class Spider:
    def init(self, ext=None):
        global _key
        if ext:
            try:
                j = ext if isinstance(ext, dict) else json.loads(ext)
                if isinstance(j, dict):
                    _key = j.get("key") or _key
            except Exception:
                pass
        _build()
        return _real.init(ext) if hasattr(_real, "init") else None

    def __getattr__(self, name):
        _build()
        return getattr(_real, name)

if __name__ == "__main__":
    _build()
    print("解密成功，Spider 类已就绪：", type(_real))
